<?php// If we are outside SMF throw an error.if (!defined('SMF'))	die('Hacking attempt...');// Add admin settings.function pages_admin_area(&$admin_areas){	global $txt;		loadLanguage('Pages');		$admin_areas += array('pages' => array(		'title' => $txt['pages_directory_admin'],		'permission' => array('admin_forum'),		'areas' => array(				'pages' => array(					'label' => $txt['pages_directory_admin'],					'file' => 'PagesAdmin.php',					'function' => 'PagesAdminMenu',					'icon' => 'posts',					'subsections' => array(		                'main' => array($txt['pages_directory_admin']),			            'add_page' => array($txt['add_pages']),		            ),				),			),		),	);	return $admin_areas;}// Set up the permisisons.function load_pages_permissions(&$permissionGroups, &$permissionList){     $permissionList['membergroup'] += array(        'view_pages' => array(false, 'pages', 'pages')    );}//Action Jackson right here lol :D.function pages_actions(&$actionArray){	$actionArray['pages'] = array('Subs-Pages.php', 'PagesMenu');}//Add the pages button at the navigation.function pages_menu_button(&$menu_buttons){	global $scripturl, $txt;		loadLanguage('Pages');		$pages = array(		'pages' => array(			'title' => $txt['pages_nav_menu'],			'href' => $scripturl . '?action=pages',			'show' => allowedTo('view_pages'),			'icon' => 'posts',		),	);			$position = array_search('login', array_keys($menu_buttons));	if($position === false) 	{		$menu_buttons = array_merge($menu_buttons, $pages);	}	else 	{		$menu_buttons = array_merge(			array_slice($menu_buttons, 0, $position),			$pages,			array_slice($menu_buttons, $position)		);	}}// Pages menufunction PagesMenu(){	global $context, $txt, $scripturl;		if(!allowedTo('view_pages'))		fatal_lang_error('no_access', false);		loadLanguage('Pages');	$context['page_title'] = $txt['pages_nav_menu'];		$context['linktree'][] = array(		'url' => $scripturl . '?action=pages',		'name' => $txt['pages_nav_menu'],	);	$subActions = array(		'pages' => 'DisplayPages',		'view' => 'ViewPages',	);    // Call the right function for this sub-acton.	if (!isset($_REQUEST['sa']) || !isset($subActions[$_REQUEST['sa']]))		$sub_action = 'pages';	else		$sub_action = $_REQUEST['sa'];	$subActions[$sub_action]();}// Display pages.function DisplayPages(){	global $txt, $sourcedir, $scripturl, $context, $smcFunc;		loadLanguage('Pages');		$listOptions = array(		'id' => 'pages_list',		'items_per_page' => 20,		'base_href' => $scripturl . '?action=pages',		'default_sort_col' => 'title',		'no_items_label' => $txt['no_pages_added_yet'],		'get_items' => array(			'function' => 'list_getPages',		),		'get_count' => array(			'function' => 'list_countPages',		),		'columns' => array(			'title' => array(				'header' => array(					'value' => $txt['title'],				),				'data' => array(					'db' => 'title',					'style' => 'width: 40%; text-align:center',				),				'sort' =>  array(					'default' => 'title',					'reverse' => 'title DESC',				),			),			'user_id' => array(				'header' => array(					'value' => $txt['username'],				),				'data' => array(					'db' => 'user_id',					'style' => 'width: 20%; text-align: center;',				),				'sort' =>  array(					'default' => 'user_id',					'reverse' => 'user_id DESC',				),			),			'views' => array(				'header' => array(					'value' => $txt['views'],				),				'data' => array(					'db' => 'views',					'style' => 'width: 5%; text-align: center;',				),				'sort' =>  array(					'default' => 'views',					'reverse' => 'views DESC',				),			),			'time' => array(				'header' => array(					'value' => $txt['page_time'],				),				'data' => array(					'db' => 'time',					'style' => 'width: 35%; text-align: center;',				),				'sort' =>  array(					'default' => 'time',					'reverse' => 'time DESC',				),			),		),		'form' => array(			'href' => $scripturl . '?action=pages',		),	);			require_once($sourcedir . '/Subs-List.php');	createList($listOptions);	$context['sub_template'] = 'show_list';	$context['default_list'] = 'pages_list';}// Get all added pages.function list_getPages($start, $items_per_page, $sort){	global $smcFunc, $scripturl, $txt;		$result = $smcFunc['db_query']('', '	       SELECT p.id, p.user_id, p.title, p.content, p.views, p.time,		   mem.id_member, mem.member_name		   FROM {db_prefix}pages AS p		   LEFT JOIN {db_prefix}members AS mem ON (mem.id_member = p.user_id)		   ORDER BY {raw:sort}		   LIMIT {int:start}, {int:per_page}',		   array(				 'sort' => $sort,		         'start' => $start,			     'per_page' => $items_per_page,			    )	);	    $pages = array();		while ($row = $smcFunc['db_fetch_assoc']($result))	{		$pages[] = array(		    'id' => $row['id'],			'title' => '<a href="' . $scripturl . '?action=pages;sa=view;id='.$row['id']. '">' . $row['title'] . '</a>',			'user_id' => !empty($row['user_id']) ? '<a href="' . $scripturl . '?action=profile;u=' . $row['user_id'] . '">' . $row['member_name'] . '</a>' : $txt['guest'],			'views' => $row['views'],			'time' => timeformat($row['time']),		);	}		return $pages;	$smcFunc['db_free_result']($result);}// Count all added pages for the pagination.function list_countPages(){	global $smcFunc;		$result = $smcFunc['db_query']('', '		SELECT COUNT(*)		FROM {db_prefix}pages',		array( )	);					list ($pages) = $smcFunc['db_fetch_row']($result);		$smcFunc['db_free_result']($result);	return $pages;}// View pages.function ViewPages(){    global $smcFunc, $context, $scripturl, $txt;		$id = (int) (isset($_REQUEST['id']) ? $_REQUEST['id'] : 0);		if(empty($id))		fatal_lang_error('page_is_deleted', false);		if(!allowedTo('view_pages'))		fatal_lang_error('no_access', false);		loadLanguage('Pages');    loadTemplate('Pages');		$context['sub_template'] = 'view_page';		$title = $smcFunc['db_query']('', '		SELECT id, title	    FROM {db_prefix}pages	    WHERE id = {int:page_id} 		LIMIT 1',		array(			'page_id' => $id,		)	);	$pageTitle = $smcFunc['db_fetch_assoc']($title);	$smcFunc['db_free_result']($title);		$context['page_title'] = $txt['viewing_page'] . $pageTitle['title'];		$context['linktree'][] = array(		'url' => $scripturl . '?action=pages;sa=view;id=' . $id,		'name' => $txt['viewing_page'] . $pageTitle['title'],	); 	$page = $smcFunc['db_query']('', '		SELECT p.id, p.user_id, p.title, p.content, p.views, p.time,		mem.id_member, mem.member_name		FROM {db_prefix}pages AS p		LEFT JOIN {db_prefix}members AS mem ON (mem.id_member = p.user_id)		WHERE p.id = {int:id}		LIMIT 1',        array(		        'id' => $id,		     )	    );			$context['pagedata'] = array();		while ($row = $smcFunc['db_fetch_assoc']($page))	{			$context['pagedata'][$row['id']] = array(		    'id' => $row['id'],		    'title' => '<a href="' . $scripturl . '?action=pages;sa=view;id='.$row['id']. '">' . $row['title'] . '</a>',			'content' => parse_bbc($row['content']),			'user_id' => !empty($row['user_id']) ? '<a href="' . $scripturl . '?action=profile;u=' . $row['user_id'] . '">' . $row['member_name'] . '</a>' : $txt['guest'],			'views' => $row['views'],			'time' => timeformat($row['time']),	    );	}		$smcFunc['db_free_result']($page);		UpdatePageViews();}// Update page views.function UpdatePageViews(){    global $smcFunc, $user_info;		$id = (int) (isset($_REQUEST['id']) ? $_REQUEST['id'] : 0);		if(empty($id))		fatal_lang_error('page_is_deleted', false);		$results = $smcFunc['db_query']('', '		SELECT user_id		FROM {db_prefix}pages		WHERE id = {int:id} 		LIMIT 1',		array(			'id' => $id,		)	);		list ($owner) = $smcFunc['db_fetch_row']($results);	$smcFunc['db_free_result']($results);		if ($owner != $user_info['id'])	{	    $smcFunc['db_query']('', '		    UPDATE {db_prefix}pages		    SET views = views + 1		    WHERE id = {int:id}',		    array(			    'id' => $id,		    )	    );	}}